import{_ as t,o as a,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse(`{"title":"ATLAS – Runtime Foundation","description":"L'état actuel du développement du framework modulaire ATLAS.","frontmatter":{"title":"ATLAS – Runtime Foundation","description":"L'état actuel du développement du framework modulaire ATLAS.","date":"2026-08-02","author":"UGSo Software","tags":["ATLAS","TypeScript","Architektur"]},"headers":[],"relativePath":"fr/blog/posts/atlas-runtime-foundation.md","filePath":"fr/blog/posts/atlas-runtime-foundation.md","lastUpdated":1793198184000}`),s={name:"fr/blog/posts/atlas-runtime-foundation.md"};function r(o,e,l,u,d,p){return a(),n("div",null,[...e[0]||(e[0]=[i('<p><a id="atlas-runtime-foundation"></a><a id="statut"></a></p><h1 id="atlas-–-runtime-foundation" tabindex="-1">ATLAS – Runtime Foundation <a class="header-anchor" href="#atlas-–-runtime-foundation" aria-label="Permalink to &quot;ATLAS – Runtime Foundation {#atlas-–-runtime-foundation}&quot;">​</a></h1><p><strong>2 août 2026 · ATLAS</strong></p><p>ATLAS est un framework TypeScript modulaire destiné à des applications, des plugins et des outils liés à Home Assistant, conçus pour être réutilisables.</p><h2 id="aktueller-stand" tabindex="-1">État actuel <a class="header-anchor" href="#aktueller-stand" aria-label="Permalink to &quot;État actuel {#aktueller-stand}&quot;">​</a></h2><p>La structure fondamentale du dépôt (repository) et de la documentation est finalisée.</p><p>Les éléments suivants sont déjà implémentés :</p><ul><li>Monorepo avec des espaces de travail (workspaces) <code>pnpm</code></li><li>Documents de gouvernance et d&#39;architecture</li><li>Couche d&#39;événements et de contrats</li><li>Contrats d&#39;événements publics</li><li>Implémentation de référence <code>DefaultEventBus</code></li><li>Tests pour les composants de base</li></ul><h2 id="nachster-sprint" tabindex="-1">Prochain sprint <a class="header-anchor" href="#nachster-sprint" aria-label="Permalink to &quot;Prochain sprint {#nachster-sprint}&quot;">​</a></h2><p>La prochaine étape de développement consiste à :</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sprint G2.5.3 – Runtime Foundation</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>L&#39;accent est mis sur :</p><ul><li>Conteneurs de services</li><li>Injection de dépendances</li><li>Descriptions de services</li><li>Résolution contrôlée des dépendances</li><li>Contrats d&#39;exécution (runtime) stables</li></ul><h2 id="langfristiges-ziel" tabindex="-1">Objectif à long terme <a class="header-anchor" href="#langfristiges-ziel" aria-label="Permalink to &quot;Objectif à long terme {#langfristiges-ziel}&quot;">​</a></h2><p>ATLAS a pour vocation de constituer une base technique commune pour plusieurs projets UGSo.</p><p>La <strong>Lovelace UV Card</strong> reste prévue comme projet ultérieur, dédié à l&#39;indice UV, au statut de protection et aux tableaux de bord visuels pour Home Assistant.</p><h2 id="mehr-erfahren" tabindex="-1">En savoir plus <a class="header-anchor" href="#mehr-erfahren" aria-label="Permalink to &quot;En savoir plus {#mehr-erfahren}&quot;">​</a></h2><p><a href="/fr/projects/atlas/">Ouvrir la page du projet ATLAS</a></p>',18)])])}const h=t(s,[["render",r]]);export{m as __pageData,h as default};
